namespace sarif.export.props;






using ghidra.framework.options;
using ghidra.program.model.listing;
using ghidra.util.exception;
using ghidra.util.task;
using sarif.export;
using sarif.export;
using sarif.managers;

public class SarifPropertyListWriter : AbstractExtWriter {

	Program program;
	List<string> options;

	public SarifPropertyListWriter(Program program, List<string> request, Writer baseWriter)
    : base(baseWriter)
    {
		this.program = program;
		this.options = request;
	}

	/* @Override */
	protected void genRoot(TaskMonitor monitor)
    {
		genList(monitor);
		root.add("properties", objects);
	}

	private void genList(TaskMonitor monitor)
    {
		monitor.initialize(options.size());
		foreach (string listName in options) {
			Options propList = program.getOptions(listName);
			List<string> propNames = propList.getOptionNames();
			Collections.sort(propNames);
			foreach (string name in propNames) {
				monitor.checkCancelled();
				if (propList.isAlias(name)) { // don't write out properties that are just mirrors of some other property
					continue;
				}
				if (propList.isDefaultValue(name)) { // don't write out default properties.
					continue;
				}
				string keyName =  listName + Options.DELIMITER_STRING + name;
				ExtProperty isf = new ExtProperty(keyName, propList);
				SarifObject sarif = new SarifObject(PropertiesSarifMgr.SUBKEY, PropertiesSarifMgr.KEY, getTree(isf), null);
				objects.add(getTree(sarif));
			}
		}
	}

}
